import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  getDocs,
  orderBy,
  query,
  serverTimestamp,
  updateDoc,
  where,
} from "firebase/firestore";
import type { QuoteItem } from "../../features/admin/types";

export type CreateQuoteItemInput = {
  quoteId: string;
  sortOrder: number;
  description: string;
  descriptionFr?: string;
  descriptionEs?: string;
  priceMXN: number;
  priceCAD: number;
  priceUSD: number;
  createdBy: string;
};

export type UpdateQuoteItemInput = Partial<Omit<CreateQuoteItemInput, "createdBy" | "quoteId">> & {
  updatedBy: string;
};

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

export async function createQuoteItem(input: CreateQuoteItemInput): Promise<string> {
  const db = await getDb();
  const ref = await addDoc(collection(db, "quoteItems"), {
    quoteId: input.quoteId,
    sortOrder: input.sortOrder,
    description: input.description,
    descriptionFr: input.descriptionFr ?? null,
    descriptionEs: input.descriptionEs ?? null,
    priceMXN: input.priceMXN,
    priceCAD: input.priceCAD,
    priceUSD: input.priceUSD,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
    createdBy: input.createdBy,
    updatedBy: null,
  });
  return ref.id;
}

export async function updateQuoteItem(id: string, input: UpdateQuoteItemInput): Promise<void> {
  const db = await getDb();
  const payload: Record<string, unknown> = { updatedAt: serverTimestamp() };
  for (const [key, value] of Object.entries(input)) {
    payload[key] = value ?? null;
  }
  await updateDoc(doc(db, "quoteItems", id), payload);
}

export async function listItemsByQuote(quoteId: string): Promise<(QuoteItem & { id: string })[]> {
  const db = await getDb();
  const q = query(
    collection(db, "quoteItems"),
    where("quoteId", "==", quoteId),
    orderBy("sortOrder", "asc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as QuoteItem) }));
}

export async function deleteQuoteItem(id: string): Promise<void> {
  const db = await getDb();
  await deleteDoc(doc(db, "quoteItems", id));
}
