import React, { useEffect, useState } from "react";
import type { HeadFC, PageProps } from "gatsby";
import SEO from "../../../components/seo";
import rawData from "../../../data/data.json";
import type { Quote, QuoteItem, QuoteCurrency, QuoteLanguage, UserProfile } from "../../../features/admin/types";
import { getQuoteByToken } from "../../../sessionServices/quotes/quotesService";
import { listItemsByQuote } from "../../../sessionServices/quotes/quoteItemsService";
import { getUserById } from "../../../sessionServices/users/usersService";
import images from "../../../images";

type QuoteWithId = Quote & { id: string };
type QuoteItemWithId = QuoteItem & { id: string };

const companyData = {
  companyName: rawData.name,
  address: rawData.address,
  city: rawData.city,
  province: rawData.province,
  country: "Canada",
  phone: rawData.phone,
  email: rawData.email,
  instagram: rawData.instagram,
  facebook: rawData.facebook,
  linkedin: "",
  postalCode: rawData.postalCode,
  url: rawData.url,
  whatsapp: "",
  menu: rawData.menu,
};

// ─── i18n strings ─────────────────────────────────────────────────────────────
const LABELS = {
  en: {
    quoteTitle: "Travel Quote",
    description: "Description",
    price: "Price",
    total: "Total",
    validUntil: "Valid until",
    preparedBy: "Prepared by",
    preparedFor: "Prepared for",
    page: "Page",
    of: "of",
    contactUs: "Contact us",
    phone: "Phone",
    email: "Email",
    website: "Website",
    thankYou: "Thank you for choosing Jenny Adventures",
    currency: "Currency",
    language: "Language",
  },
  fr: {
    quoteTitle: "Devis de voyage",
    description: "Description",
    price: "Prix",
    total: "Total",
    validUntil: "Valide jusqu'au",
    preparedBy: "Préparé par",
    preparedFor: "Préparé pour",
    page: "Page",
    of: "de",
    contactUs: "Contactez-nous",
    phone: "Téléphone",
    email: "Courriel",
    website: "Site web",
    thankYou: "Merci de choisir Jenny Adventures",
    currency: "Devise",
    language: "Langue",
  },
  es: {
    quoteTitle: "Cotización de viaje",
    description: "Descripción",
    price: "Precio",
    total: "Total",
    validUntil: "Válido hasta",
    preparedBy: "Preparado por",
    preparedFor: "Preparado para",
    page: "Página",
    of: "de",
    contactUs: "Contáctanos",
    phone: "Teléfono",
    email: "Correo",
    website: "Sitio web",
    thankYou: "Gracias por elegir Jenny Adventures",
    currency: "Moneda",
    language: "Idioma",
  },
} as const;

const CURRENCY_SYMBOL: Record<QuoteCurrency, string> = {
  MXN: "MX$",
  CAD: "CA$",
  USD: "US$",
};

const CURRENCIES: QuoteCurrency[] = ["MXN", "CAD", "USD"];
const LANGUAGES: { value: QuoteLanguage; label: string }[] = [
  { value: "en", label: "English" },
  { value: "fr", label: "Français" },
  { value: "es", label: "Español" },
];

function getItemDescription(item: QuoteItem, lang: QuoteLanguage): string {
  if (lang === "fr" && item.descriptionFr) return item.descriptionFr;
  if (lang === "es" && item.descriptionEs) return item.descriptionEs;
  return item.description;
}

function getPrice(item: QuoteItem, currency: QuoteCurrency): number {
  if (currency === "MXN") return item.priceMXN ?? 0;
  if (currency === "CAD") return item.priceCAD ?? 0;
  return item.priceUSD ?? 0;
}

function formatPrice(amount: number, currency: QuoteCurrency): string {
  return `${CURRENCY_SYMBOL[currency]} ${amount.toLocaleString("en-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

// ─── Component ────────────────────────────────────────────────────────────────
export default function SharedQuotePage({ params, location }: PageProps) {
  const token = params["token"];
  const searchParams = typeof window !== "undefined"
    ? new URLSearchParams(window.location.search)
    : new URLSearchParams(location.search);

  const defaultLang = (searchParams.get("lang") as QuoteLanguage) || "en";
  const defaultCurrency = (searchParams.get("currency") as QuoteCurrency) || "CAD";

  const [quote, setQuote] = useState<QuoteWithId | null>(null);
  const [items, setItems] = useState<QuoteItemWithId[]>([]);
  const [client, setClient] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [lang, setLang] = useState<QuoteLanguage>(defaultLang);
  const [currency, setCurrency] = useState<QuoteCurrency>(defaultCurrency);

  useEffect(() => {
    async function load() {
      const data = await getQuoteByToken(token) as QuoteWithId | null;
      if (!data) { setNotFound(true); setLoading(false); return; }
      const [itemsData, clientData] = await Promise.all([
        listItemsByQuote(data.id),
        getUserById(data.userId),
      ]);
      setQuote(data);
      setItems(itemsData);
      setClient(clientData);
      document.title = `${data.title} — Jenny Adventures`;
      setLoading(false);
    }
    load();
  }, [token]);

  const t = LABELS[lang];
  const total = items.reduce((s, i) => s + getPrice(i, currency), 0);

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (notFound || !quote) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4">
        <div className="text-center">
          <p className="text-5xl font-bold text-gray-200">404</p>
          <h1 className="mt-4 text-lg font-semibold text-gray-800">Quote not found</h1>
          <p className="mt-2 text-sm text-gray-500">
            This link may have expired or been revoked. Please contact your travel agent.
          </p>
        </div>
      </div>
    );
  }

  return (
    <>
      <style>{PRINT_CSS}</style>

      <div className="min-h-screen bg-gray-50 print:bg-white">
        {/* ── Controls bar (screen only) ── */}
        <div className="no-print sticky top-0 z-10 flex items-center justify-between gap-4 border-b border-gray-200 bg-white px-4 py-2 shadow-sm">
          <span className="text-xs font-medium text-gray-500 uppercase tracking-wide">Preview</span>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <label className="text-xs text-gray-500">{t.language}:</label>
              <select
                value={lang}
                onChange={(e) => setLang(e.target.value as QuoteLanguage)}
                className="rounded border border-gray-300 px-2 py-1 text-xs focus:outline-none"
              >
                {LANGUAGES.map((l) => (
                  <option key={l.value} value={l.value}>{l.label}</option>
                ))}
              </select>
            </div>
            <div className="flex items-center gap-2">
              <label className="text-xs text-gray-500">{t.currency}:</label>
              <select
                value={currency}
                onChange={(e) => setCurrency(e.target.value as QuoteCurrency)}
                className="rounded border border-gray-300 px-2 py-1 text-xs focus:outline-none"
              >
                {CURRENCIES.map((c) => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </div>
            <button
              onClick={() => window.print()}
              className="rounded-lg bg-gray-900 px-3 py-1.5 text-xs font-medium text-white transition hover:bg-gray-700"
            >
              Print / PDF
            </button>
          </div>
        </div>

        {/* ── Document ── */}
        <div id="quote-document" className="mx-auto max-w-3xl px-6 py-10 print:max-w-none print:px-0 print:py-0">

          {/* Header — agency + quote meta */}
          <header className="quote-header mb-6 flex items-start justify-between border-b-2 border-gray-900 pb-6 print:mb-5">
            <div className="flex items-center gap-3">
              <img
                src={images.logo.src}
                alt="Jenny Adventures"
                className="h-16 w-auto"
              />
              <div>
                <p className="text-xl font-bold text-gray-900">Jenny Adventures</p>
                <p className="text-xs text-gray-500">{rawData.city}, {rawData.province}</p>
              </div>
            </div>
            <div className="text-right">
              <p className="text-2xl font-bold text-gray-900">{t.quoteTitle}</p>
              {quote.validUntil && (
                <p className="mt-1 text-xs text-gray-500">
                  {t.validUntil}: {(quote.validUntil as { toDate: () => Date }).toDate().toLocaleDateString(
                    lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA"
                  )}
                </p>
              )}
            </div>
          </header>

          {/* Quote title + client info */}
          <div className="mb-6 flex flex-wrap items-start justify-between gap-4 rounded-lg bg-gray-50 px-5 py-4 print:bg-white print:px-0 print:border-b print:border-gray-200 print:pb-4">
            <div>
              <p className="text-xs font-semibold uppercase tracking-wide text-gray-400 mb-1">
                {t.quoteTitle}
              </p>
              <h1 className="text-lg font-bold text-gray-900">{quote.title}</h1>
            </div>
            {client && (
              <div className="text-right">
                <p className="text-xs font-semibold uppercase tracking-wide text-gray-400 mb-1">
                  {t.preparedFor}
                </p>
                <p className="text-sm font-semibold text-gray-900">{client.fullName}</p>
                {client.email && (
                  <p className="text-xs text-gray-500">{client.email}</p>
                )}
                {client.phoneNumber && (
                  <p className="text-xs text-gray-500">{client.phoneNumber}</p>
                )}
              </div>
            )}
          </div>

          {/* Items table */}
          <table className="quote-table w-full border-collapse text-sm">
            <thead>
              <tr className="bg-gray-900 text-white">
                <th className="px-4 py-3 text-left font-semibold w-8">#</th>
                <th className="px-4 py-3 text-left font-semibold">{t.description}</th>
                <th className="px-4 py-3 text-right font-semibold whitespace-nowrap">
                  {t.price} ({currency})
                </th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, idx) => (
                <tr
                  key={item.id}
                  className={idx % 2 === 0 ? "bg-white" : "bg-gray-50"}
                  style={{ pageBreakInside: "avoid" }}
                >
                  <td className="px-4 py-3 text-gray-400 align-top text-xs">{idx + 1}</td>
                  <td className="px-4 py-3 text-gray-800 align-top whitespace-pre-wrap leading-relaxed">
                    {getItemDescription(item, lang)}
                  </td>
                  <td className="px-4 py-3 text-right align-top font-mono text-gray-900 whitespace-nowrap">
                    {formatPrice(getPrice(item, currency), currency)}
                  </td>
                </tr>
              ))}

              {/* Total row */}
              <tr className="border-t-2 border-gray-900 bg-gray-900 text-white font-semibold">
                <td className="px-4 py-3" colSpan={2}>{t.total}</td>
                <td className="px-4 py-3 text-right font-mono whitespace-nowrap">
                  {formatPrice(total, currency)}
                </td>
              </tr>
            </tbody>
          </table>

          {/* Footer spacer for print */}
          <div className="print-footer-spacer" />
        </div>

        {/* ── Print footer (repeated on each page via CSS) ── */}
        <div className="quote-page-footer">
          <div className="footer-inner">
            <span><span className="footer-label">{t.phone}:</span> {rawData.phone}</span>
            <span><span className="footer-label">{t.email}:</span> {rawData.email}</span>
            <span><span className="footer-label">{t.website}:</span> {rawData.url}</span>
          </div>
          <p className="footer-tagline">{t.thankYou}</p>
        </div>
      </div>
    </>
  );
}

export const Head: HeadFC = () => (
  <SEO
    data={companyData}
    title="Your Quote — Jenny Adventures"
    description="View your personalized travel quote prepared by Jenny Adventures."
    pathname="/app/quote"
    noindex
  />
);

// ─── Print CSS ────────────────────────────────────────────────────────────────
// Footer height is ~14mm. @page bottom margin = 22mm leaves 8mm gap above footer.
// The footer sits at position: fixed; bottom: 0 which anchors it to the bottom
// of the @page content area (inside margins) on every printed page.
// padding-bottom on #quote-document prevents content from sliding under the footer.
const PRINT_CSS = `
  @page {
    size: Letter;
    margin: 18mm 15mm 22mm 15mm;
  }

  @media print {
    * {
      -webkit-print-color-adjust: exact !important;
      print-color-adjust: exact !important;
    }

    body {
      background: #fff !important;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .no-print {
      display: none !important;
    }

    #quote-document {
      max-width: 100% !important;
      padding: 0 0 20mm 0 !important;
      margin: 0 !important;
    }

    .quote-table {
      border-collapse: collapse;
      width: 100%;
    }

    .quote-table th,
    .quote-table td {
      border: 1px solid #e5e7eb;
    }

    .quote-table thead tr th {
      background-color: #111827 !important;
      color: #fff !important;
    }

    .quote-table tbody tr:nth-child(even) td {
      background-color: #f9fafb !important;
    }

    .quote-table tbody tr:last-child td {
      background-color: #111827 !important;
      color: #fff !important;
    }

    /* Footer fixed at bottom of every printed page */
    .quote-page-footer {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      height: 14mm;
      border-top: 1.5px solid #111827;
      padding: 3mm 0 2mm;
      background: #fff;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .footer-inner {
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 7.5pt;
      color: #6b7280;
    }

    .footer-label {
      font-weight: 600;
      color: #374151;
    }

    .footer-tagline {
      text-align: center;
      font-size: 7pt;
      color: #9ca3af;
      margin-top: 1.5mm;
    }

    /* Page numbers via @page margin box (Chrome 117+) */
    @page {
      @bottom-right {
        content: counter(page) " / " counter(pages);
        font-size: 7.5pt;
        color: #6b7280;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }
    }

    .print-footer-spacer {
      display: none;
    }
  }

  @media screen {
    .quote-page-footer {
      display: none;
    }

    .print-footer-spacer {
      display: none;
    }
  }
`;
